C(5, 2, "Sus quejas, una pista", [
 ("gancho", "marisol", "[curioso, intriga, ritmo ágil] ¿Qué es lo que más te reclama tu hijo? Piensa en la última semana."),
 ("joven1", "rewe", "[adolescente, molesto, directo] ¡Nunca me escuchas!"),
 ("joven2", "rewe", "[adolescente, molesto, directo] ¡Siempre me estás criticando!"),
 ("idea", "marisol", "[cálido, cercano, ritmo ágil] Chapman sugiere prestar atención a las quejas de tu hijo. Y no para defenderte. Lo que parece pura inconformidad puede estar señalando cómo necesita recibir amor."),
 ("cita", "marisol", "[firme, cálido, pausado] Sobre las quejas, escribe: «Cuando varias de estas caen dentro de la misma categoría, es probable que revelen el lenguaje primario de amor del joven». Es decir, no una queja aislada, sino las que se repiten."),
 ("giro", "marisol", "[cálido, cercano, ritmo ágil] Ahora, ¿qué lenguajes hay? El libro habla de cinco: palabras de afirmación, toque físico, tiempo de calidad, actos de servicio y regalos. Uno de ellos es el primario."),
 ("accion", "marisol", "[firme, cálido, cierre] Para hoy: anota las últimas tres quejas que tu hijo te ha hecho, y fíjate si se parecen entre sí. No para discutirlas. Solo para entender. Sin defenderte."),
 ("siguiente", "marisol", "[sereno, cierre] Siguiente: qué decirle cuando hizo algo a medias."),
], [
 ("titular", "gancho", "reclama", "¿Qué te reclama más?", "Burbujas de queja que suben y se apilan"),
 ("reaccion", "joven1", "escuchas", "¡Nunca me escuchas!", "Burbuja de queja del adolescente"),
 ("reaccion", "joven2", "criticando", "¡Siempre me estás criticando!", "Segunda burbuja de queja, se apila sobre la primera"),
 ("icono", "idea", "quejas", "Sus quejas: una pista", "Lupa sobre una burbuja de queja que revela un corazón"),
 ("cita", "cita", "categoría", "«Cuando varias de estas caen dentro de la misma categoría, es probable que revelen el lenguaje primario de amor del joven»", "Tarjeta de cita: Gary Chapman, Los 5 lenguajes del amor de los jóvenes"),
 ("icono", "cita", "lenguaje", "Lenguaje primario de amor", "Tres burbujas de queja caen en un mismo cajón"),
 ("icono", "giro", "afirmación", "Afirmación", "Icono de globo de diálogo con estrella"),
 ("icono", "giro", "toque", "Toque físico", "Icono de dos manos que chocan"),
 ("icono", "giro", "tiempo", "Tiempo de calidad", "Icono de reloj con corazón"),
 ("icono", "giro", "servicio", "Actos de servicio", "Icono de delantal y cuchara"),
 ("icono", "giro", "regalos", "Regalos", "Icono de caja de regalo"),
 ("accion", "accion", "quejas", "Para hoy: anota sus últimas tres quejas", "Tarjeta «Para hoy» con tres líneas que se llenan"),
 ("titular", "siguiente", "medias", "Siguiente: cuando lo hizo a medias", "Un hilo de tejido sin terminar"),
], [GB + ", Chapman: «Cuando varias de estas caen dentro de la misma categoría…» (PT119)", "Los cinco lenguajes: ficha oficial 5lovelanguages.com"])

C(5, 3, "El césped sin cortar", [
 ("gancho", "marisol", "[curioso, intriga, ritmo ágil] Tu hijo cortó el césped, pero dejó partes sin cortar. ¿Qué le dices?"),
 ("papa1", "mario", "[papá, molesto, tajante] ¡Mira nomás! ¡Esto no es cortar el pasto! ¡Aquí se te quedó todo sin cortar!"),
 ("idea", "marisol", "[cálido, cercano, ritmo ágil] Chapman cuenta un ejemplo cotidiano: el de un joven que corta el césped y deja zonas sin cortar. Y le aconseja al papá algo difícil: aguantarse."),
 ("cita", "marisol", "[firme, cálido, pausado] El consejo es: «Refrénate, no señales el césped sin cortar». Esa parte se puede corregir la semana siguiente. Primero, lo que sí hizo. En cambio, propone decirle algo como esto."),
 ("papa2", "mario", "[papá, cálido, sincero] «Aprecio mucho tu gran esfuerzo»."),
 ("giro", "marisol", "[cálido, cercano, ritmo ágil] Así, explica Chapman, el trabajo empieza a parecerle valioso, y su tanque de amor se va llenando."),
 ("accion", "marisol", "[firme, cálido, cierre] Para hoy: la próxima vez que haga algo a medias, reconoce primero su esfuerzo. La corrección puede esperar a otro momento."),
 ("tarjeta", "marisol", TARJ + "Los cinco lenguajes del amor de los jóvenes, de Gary Chapman, de Editorial Unilit. Este video no sustituye la lectura del libro."),
], [
 ("titular", "gancho", "césped", "¿Qué le dices?", "Césped recién cortado con franjas sin cortar; sin personas"),
 ("reaccion", "papa1", "sin", "¡Aquí se te quedó todo sin cortar!", "Burbuja de papá sobre las franjas de pasto"),
 ("titular", "idea", "aguantarse", "Primero: aguantarse", "Palabra «aguantarse» con una pausa (dos barras) en amarillo"),
 ("cita", "cita", "Refrénate", "«Refrénate, no señales el césped sin cortar»", "Tarjeta de cita: Gary Chapman, Los 5 lenguajes del amor de los jóvenes"),
 ("icono", "cita", "semana", "Se corrige la semana siguiente", "Calendario con una hoja que pasa"),
 ("cita", "papa2", "Aprecio", "«Aprecio mucho tu gran esfuerzo»", "Tarjeta de cita corta con atribución a Chapman (frase de ejemplo del libro)"),
 ("icono", "giro", "tanque", "El tanque se va llenando", "Tanque que sube de nivel con gotas amarillas"),
 ("accion", "accion", "esfuerzo", "Para hoy: primero reconoce su esfuerzo", "Tarjeta «Para hoy» con palomita"),
 ("icono", "accion", "corrección", "La corrección puede esperar", "Un reloj de arena que se voltea"),
 ("tarjeta_libro", "tarjeta", "Unilit", "Los 5 lenguajes del amor de los jóvenes · Gary Chapman · Editorial Unilit", "Tarjeta de cierre estándar de la serie: portada tipográfica, sin foto; leyenda «Este video no sustituye la lectura del libro»"),
], [GB + ", Chapman: ejemplo del césped y «Aprecio mucho tu gran esfuerzo» (PT41)"])
